mviewer.customLayers.gridSearch5x5=(function(){class GridSearch5x5Layer extends mviewer.customLayers.SinpBaseLayer{constructor(){super("gridSearch5x5","fn_get_stats",{maxZoom:12,serverRenderOnly:!0,serverStyle:{enabled:!0,legendTypeName:"fn_get_legend",allowedStyleNames:mviewer.customLayers.SinpBaseLayer.STATS_STYLE_NAMES},style:new ol.style.Style({stroke:new ol.style.Stroke({color:"rgba(0, 0, 0, 0.001)",width:1}),fill:new ol.style.Fill({color:"rgba(0, 0, 0, 0.001)"})})})}}const instance=new GridSearch5x5Layer;return{layer:instance.getLayer(),handle:!1,get_datas:function(params,options){return SinpBaseCustom.refreshSearchLayer("gridSearch5x5",params,options)},_instance:instance}})();
